<canvas id="film" width="960" height="540"
 aria-label="Walk Anyway, an illustrated short film"></canvas>
<button id="play">Play</button>
<script>
const canvas=document.querySelector('canvas'),
 ctx=canvas.getContext('2d'),button=document.querySelector('button');
let running=false,start=0,previous=0,said=false,audio,rainGain;
const W=960,H=540;
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const ease=v=>{v=clamp(v);return v*v*(3-2*v)};
function rect(x,y,w,h,color){
 ctx.fillStyle=color;ctx.fillRect(x,y,w,h);
}
function line(x,y,X,Y,color,width=2){
 ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();
 ctx.moveTo(x,y);ctx.lineTo(X,Y);ctx.stroke();
}
function ellipse(x,y,rx,ry,color){
 ctx.fillStyle=color;ctx.beginPath();
 ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();
}
function path(points,color){
 ctx.fillStyle=color;ctx.beginPath();
 points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));
 ctx.closePath();ctx.fill();
}
function scene(){
 const sky=ctx.createLinearGradient(0,0,0,H);
 sky.addColorStop(0,'#08121e');sky.addColorStop(1,'#33444d');
 ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 for(let i=0;i<10;i++){
  const x=i*113-30,h=95+(i*37)%110;
  rect(x,330-h,94,h,'#101d29');
  for(let j=0;j<3;j++)
   rect(x+14+j*25,345-h,7,12,'#5a625e');
 }
 rect(0,365,W,175,'#192b35');
 for(let i=0;i<34;i++)
  rect((i*139)%960,385+(i*31)%150,25+i%4*12,2,
    i%3?'#354b54':'#777355');
 // Street lamp.
 line(820,90,820,382,'#606e73',6);
 line(820,90,767,90,'#606e73',6);
 ellipse(766,96,15,5,'#e6ddaa');
 const light=ctx.createRadialGradient(766,130,0,766,130,210);
 light.addColorStop(0,'#fff3ba18');light.addColorStop(1,'#fff3ba00');
 ctx.fillStyle=light;ctx.fillRect(550,0,410,420);
 // Bus shelter, without extra lettering.
 rect(210,190,400,174,'#8199a312');
 line(210,187,610,187,'#71838c',9);
 line(219,192,219,375,'#637780',6);
 line(601,192,601,375,'#637780',6);
 line(225,333,388,333,'#6d7a80',7);
 line(240,335,240,368,'#465a65',5);
 line(374,335,374,368,'#465a65',5);
 line(143,169,143,376,'#73848c',5);
 rect(128,155,30,36,'#bdc5bf');
}
function umbrella(x,y,s=1){
 ctx.save();ctx.translate(x,y);ctx.scale(s,s);
 line(0,-145,0,12,'#8b9291',3);
 ctx.strokeStyle='#8b9291';ctx.lineWidth=3;ctx.beginPath();
 ctx.arc(-7,12,7,0,Math.PI);ctx.stroke();
 ctx.fillStyle='#080d14';ctx.beginPath();
 ctx.moveTo(-108,-137);
 ctx.quadraticCurveTo(-83,-216,0,-215);
 ctx.quadraticCurveTo(83,-216,108,-137);
 ctx.quadraticCurveTo(77,-152,54,-137);
 ctx.quadraticCurveTo(25,-152,0,-137);
 ctx.quadraticCurveTo(-25,-152,-54,-137);
 ctx.quadraticCurveTo(-77,-152,-108,-137);
 ctx.fill();
 line(0,-215,-54,-140,'#26313b',1);
 line(0,-215,54,-140,'#26313b',1);
 ctx.restore();
}
// All shots reuse these same character drawings.
function person(x,y,who,back=false,smile=false,walk=0,talk=false){
 const woman=who==='woman',skin=woman?'#dbb9a5':'#cfad94';
 ctx.save();ctx.translate(x,y);
 const step=Math.sin(walk)*7;
 ellipse(0,4,31,6,'#00000040');
 line(-12,-51,-13+step,-5,'#18222b',10);
 line(12,-51,13-step,-5,'#18222b',10);
 if(woman){
  rect(-23+step,-21,17,26,'#d9b63d');
  rect(5-step,-21,17,26,'#d9b63d');
  rect(-23+step,-1,24,7,'#ebca55');
  rect(5-step,-1,24,7,'#ebca55');
 }
 path([[-23,-126],[23,-126],[34,-43],[-34,-43]],
   woman?'#b8323b':'#42644f');
 line(-24,-114,-36,-69,woman?'#b8323b':'#42644f',12);
 line(24,-114,35,-76,woman?'#b8323b':'#42644f',12);
 ellipse(-36,-66,5,6,skin);ellipse(35,-73,5,6,skin);
 line(0,-121,0,-49,woman?'#e05b5a':'#6b8266',2);
 ellipse(0,-150,23,29,woman?'#c9d0d3':'#92918b');
 if(!back){
  ellipse(0,-146,17,23,skin);
  if(woman){
   path([[-23,-151],[-18,-173],[8,-179],[23,-165],
         [23,-133],[14,-132],[13,-161],[-8,-163],[-17,-139]],
        '#d3d8da');
  }else{
   path([[-18,-145],[-11,-126],[0,-117],[12,-126],[18,-145],
         [8,-137],[-8,-137]],'#b6b6ae');
  }
  ellipse(-6,-149,1.5,1.5,'#263039');
  ellipse(7,-149,1.5,1.5,'#263039');
  if(smile){
   ctx.strokeStyle='#824b4b';ctx.lineWidth=1.7;
   ctx.beginPath();ctx.arc(1,-141,7,0.25,2.8);ctx.stroke();
  }else if(talk)ellipse(1,-137,4,3,'#553b3b');
  else line(-3,-137,5,-137,'#824f4a',1.5);
 }
 ctx.restore();
}
function rain(t){
 ctx.save();ctx.strokeStyle='#d4e3ed70';ctx.lineWidth=1;
 ctx.beginPath();
 for(let i=0;i<260;i++){
  const x=((i*137.51-t*95)%1020+1020)%1020-30;
  const y=(i*67.73+t*(280+i%7*16))%590-30;
  ctx.moveTo(x,y);ctx.lineTo(x-5,y+16);
 }
 ctx.stroke();ctx.restore();
}
function card(){
 rect(0,0,W,H,'#000');
 ctx.fillStyle='#fff';ctx.textAlign='center';
 ctx.font='500 48px Arial, sans-serif';
 ctx.fillText('WALK ANYWAY',480,286);
}
function frame(t){
 ctx.setTransform(1,0,0,1,0,0);
 if(t<2||t>=28){card();return}
 scene();
 if(t<8){
  person(460,398,'woman');
 }else if(t<15){
  const p=ease((t-8)/5.8),x=1070-510*p;
  person(460,398,'woman');
  person(x,398,'man',false,false,p<1?(t-8)*8:0);
  umbrella(x-35,270);
 }else if(t<21){
  // Tight two-shot with room for the umbrella.
  ctx.save();ctx.translate(480,430);ctx.scale(2.1,2.1);
  ctx.translate(-510,-330);
  person(460,398,'woman',false,t>17.1);
  person(560,398,'man',false,false,0,t>16&&t<17.3);
  umbrella(525,270);
  ctx.restore();
 }else{
  const p=ease((t-21)/7),s=1-p*.36;
  ctx.save();ctx.translate(510+p*35,398-p*50);
  ctx.scale(s,s);
  person(-50,0,'woman',true,false,(t-21)*7);
  person(50,0,'man',true,false,(t-21)*7+1);
  umbrella(15,-128);
  ctx.restore();
 }
 rain(t);
}
async function initAudio(){
 audio=new (window.AudioContext||window.webkitAudioContext)();
 await audio.resume();
 const buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate);
 const samples=buffer.getChannelData(0);
 let low=0;
 for(let i=0;i<samples.length;i++){
  const noise=Math.random()*2-1;
  low=.93*low+.07*noise;
  samples[i]=noise*.22+low*1.4;
 }
 const source=audio.createBufferSource();
 source.buffer=buffer;source.loop=true;
 const filter=audio.createBiquadFilter();
 filter.type='lowpass';filter.frequency.value=4600;
 rainGain=audio.createGain();rainGain.gain.value=0;
 source.connect(filter).connect(rainGain).connect(audio.destination);
 source.start();
}
function speak(){
 if(!('speechSynthesis' in window))return;
 const phrase=new SpeechSynthesisUtterance('You came back.');
 phrase.lang='en-US';phrase.rate=.78;phrase.pitch=.75;
 const voices=speechSynthesis.getVoices();
 const voice=voices.find(v=>/^en/.test(v.lang)&&
   /David|Daniel|George|James|Male/i.test(v.name));
 if(voice)phrase.voice=voice;
 speechSynthesis.speak(phrase);
}
function tick(now){
 if(!running)return;
 const t=((now-start)/1000)%30;
 if(t<previous){said=false;speechSynthesis?.cancel()}
 if(!said&&t>=16&&t<21){said=true;speak()}
 if(rainGain)
  rainGain.gain.setTargetAtTime(t>=2&&t<28?.48:0,
    audio.currentTime,.06);
 frame(t);previous=t;requestAnimationFrame(tick);
}
button.onclick=async()=>{
 if(running){
  running=false;button.textContent='Play';
  window.speechSynthesis?.cancel();
  if(rainGain)rainGain.gain.value=0;
  frame(0);return;
 }
 try{
  if(!audio)await initAudio();
  else await audio.resume();
 }catch(e){/* Visual playback remains available. */}
 window.speechSynthesis?.cancel();
 running=true;said=false;previous=0;start=performance.now();
 button.textContent='Stop';requestAnimationFrame(tick);
};
frame(0);
</script>
